using System.IO;
using System.Text;
using System.Windows;
using System.Windows.Threading;
using MediaDownloader.Core.Services;

namespace MediaDownloader;

public partial class App : Application
{
    private static readonly object CrashLogLock = new();
    private static int _fatalUiGate;
    private static Mutex? _singleInstanceMutex;

    protected override void OnStartup(StartupEventArgs e)
    {
        DispatcherUnhandledException += OnDispatcherUnhandledException;
        AppDomain.CurrentDomain.UnhandledException += OnUnhandledException;
        TaskScheduler.UnobservedTaskException += OnUnobservedTaskException;

        try
        {
            base.OnStartup(e);

            var startupSettings = new AppSettingsService().Load();
            ThemeService.ApplyTheme(startupSettings.ThemeName);

            if (IsEngineContractTest())
            {
                RunEngineContractTests();
                Shutdown(0);
                return;
            }

            if (IsSettingsSmokeTestR1622())
            {
                RunSettingsSmokeTestR1622();
                Shutdown(0);
                return;
            }
            if (IsLicensedUiSmokeTestR19())
            {
                RunLicensedUiSmokeTestR19();
                Shutdown(0);
                return;
            }

            if (IsLicenseLocalReceiptTestR19())
            {
                RunLicenseLocalReceiptTestR19();
                Shutdown(0);
                return;
            }
            if (IsBuildIdentitySmokeTestR1623())
            {
                RunBuildIdentitySmokeTestR1623();
                Shutdown(0);
                return;
            }
            if (IsLicensePersistenceSmokeTestR1624())
            {
                RunLicensePersistenceSmokeTestR1624();
                Shutdown(0);
                return;
            }
            if (!IsNonInteractiveSelfTest() && !AcquireInteractiveSingleInstance())
            {
                Shutdown(0);
                return;
            }

            var window = new MainWindow();
            MainWindow = window;
            window.Show();
            if (!IsNonInteractiveSelfTest())
            {
            }
        }
        catch (Exception ex)
        {
            WriteCrashLog("Startup", ex);
            HandleFatalUiOnce(ex, "MediaDock startup error");
            Shutdown(101);
        }
    }

    private void OnDispatcherUnhandledException(object sender, DispatcherUnhandledExceptionEventArgs e)
    {
        WriteCrashLog("DispatcherUnhandledException", e.Exception);
        e.Handled = true;

        // Runtime failures are logged and the process exits without opening another
        // modal error window. A modal dialog from a failing dispatcher can itself
        // recurse while WPF is unwinding, which is exactly the failure mode this
        // release is designed to contain.
        Shutdown(102);
    }

    private static void OnUnhandledException(object? sender, UnhandledExceptionEventArgs e)
    {
        if (e.ExceptionObject is Exception ex)
        {
            WriteCrashLog("AppDomain.UnhandledException", ex);
        }
        else
        {
            WriteCrashLog("AppDomain.UnhandledException", new Exception(e.ExceptionObject?.ToString() ?? "Unknown fatal exception."));
        }
    }

    private static void OnUnobservedTaskException(object? sender, UnobservedTaskExceptionEventArgs e)
    {
        WriteCrashLog("TaskScheduler.UnobservedTaskException", e.Exception);
        e.SetObserved();
    }

    private static bool IsStartupSmokeTest() =>
        Environment.GetCommandLineArgs()
            .Any(arg => string.Equals(arg, "--startup-smoke-test", StringComparison.OrdinalIgnoreCase));

    private static bool IsEngineContractTest() =>
        Environment.GetCommandLineArgs()
            .Any(arg => string.Equals(arg, "--engine-contract-test", StringComparison.OrdinalIgnoreCase));

    private static bool IsNonInteractiveSelfTest() =>
        IsStartupSmokeTest() || IsEngineContractTest() || IsSettingsSmokeTestR1622() || IsLicensedUiSmokeTestR19() || IsLicenseLocalReceiptTestR19() || IsBuildIdentitySmokeTestR1623() || IsLicensePersistenceSmokeTestR1624();

    private static void RunEngineContractTests()
