            throw new InvalidOperationException("Queue-action contract failed for completed MP3 media.");
        }

        queueVideo.HasDownloadedMp3Counterpart = true;
        if (queueVideo.CanConvertToMp3)
        {
            throw new InvalidOperationException("Duplicate-format action contract failed: MP3 action must hide when MP3 counterpart exists.");
        }

        queueAudio.HasDownloadedMp4Counterpart = true;
        if (queueAudio.CanRedownloadAsMp4)
        {
            throw new InvalidOperationException("Duplicate-format action contract failed: MP4 action must hide when MP4 counterpart exists.");
        }

        queueVideo.HasDownloadedMp3Counterpart = false;
        queueAudio.HasDownloadedMp4Counterpart = false;
        if (!queueVideo.CanConvertToMp3 || !queueAudio.CanRedownloadAsMp4)
        {
            throw new InvalidOperationException("Duplicate-format action contract failed: action must return when counterpart is no longer available.");
        }

        var queuePersistence = new QueuePersistenceService();
        if (!queuePersistence.QueuePath.EndsWith(
