            throw new InvalidOperationException("Persistent queue storage contract failed.");
        }

        var artworkArgs = YtDlpService.BuildEmbeddedArtworkArguments();
        if (!artworkArgs.Contains("--embed-thumbnail", StringComparer.Ordinal) ||
            !artworkArgs.Contains("--embed-metadata", StringComparer.Ordinal) ||
            !artworkArgs.Contains("jpg", StringComparer.Ordinal))
