            throw new InvalidOperationException("Stream selector must require combined video+audio for direct browser playback.");
        }

        if (!TrialStateService.ProtectedReplicaWriterUsesInstanceContext)
        {
            throw new InvalidOperationException(
                "Strict trial protected-replica instance-context contract failed.");
        }

        if (TrialStateService.MaxVideoOutputs != 5 ||
            TrialStateService.MaxMp3Outputs != 5 ||
            TrialStateService.HardenedStateVersion != 2 ||
            !TrialStateService.UsesDpapiProtection ||
            !TrialStateService.UsesCredentialManagerReplica ||
            !TrialStateService.MaintainsLegacyFloor)
        {
            throw new InvalidOperationException(
                "Strict trial hardening contract failed.");
        }

        if (!string.Equals(
                LicenseProductInfo.PurchaseUrl,
                "https://payhip.com/b/oxlUS",
                StringComparison.Ordinal) ||
            !string.Equals(
                LicenseProductInfo.ReleaseThisDeviceLabel,
                "Release This Device",
                StringComparison.Ordinal) ||
            LicenseProductInfo.StandardMaxDevices != 3)
        {
            throw new InvalidOperationException(
                "MediaDock license purchase/release terminology contract failed.");
        }

        var captureManifest = WebMediaCaptureService.TryCreateCandidate(
            "https://cdn.example.com/master.m3u8",
            "application/vnd.apple.mpegurl",
            out var manifestCandidate);
        var captureVideo = WebMediaCaptureService.TryCreateCandidate(
            "https://cdn.example.com/video.mp4?token=abc",
            "video/mp4",
            out var videoCandidate);
        var captureSegment = WebMediaCaptureService.TryCreateCandidate(
            "https://cdn.example.com/segment-1.m4s",
            "video/iso.segment",
            out _);

        if (!captureManifest ||
            manifestCandidate is null ||
            !manifestCandidate.IsManifest ||
            !captureVideo ||
            videoCandidate is null ||
            !videoCandidate.IsVideo ||
            captureSegment)
        {
            throw new InvalidOperationException("Internal webpage media-capture classification contract failed.");
        }

        var importedTextUrls = BatchLinkImportService.ExtractUrlsFromText(
            "first https://example.com/video/1\n" +
            "duplicate https://example.com/video/1\n" +
            "second https://example.org/watch?v=2");
        if (importedTextUrls.Count != 2 ||
            !string.Equals(importedTextUrls[0], "https://example.com/video/1", StringComparison.Ordinal) ||
            !string.Equals(importedTextUrls[1], "https://example.org/watch?v=2", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("TXT/bulk URL extraction contract failed.");
        }

        var importedCsvUrls = BatchLinkImportService.ExtractUrlsFromCsv(
            "title,url,notes\r\n" +
            "\"One\",\"https://example.com/a,b?x=1\",\"quoted comma\"\r\n" +
            "\"Two\",\"https://example.net/video/2\",\"ok\"");
        if (importedCsvUrls.Count != 2 ||
            !importedCsvUrls[0].Contains("example.com", StringComparison.Ordinal) ||
            !importedCsvUrls[1].Contains("example.net", StringComparison.Ordinal))
        {
            throw new InvalidOperationException("CSV URL extraction contract failed.");
        }

        if (!BatchLinkImportService.IsSupportedLinkFile("links.txt") ||
            !BatchLinkImportService.IsSupportedLinkFile("links.CSV") ||
            BatchLinkImportService.IsSupportedLinkFile("links.xlsx"))
